"""Repeatable, fail-closed qualification gate for the PyBoy backend."""

from __future__ import annotations

import argparse
import hashlib
import json
from pathlib import Path
from typing import Callable

import numpy as np

from pyboy_adapter import BackendCapabilityError, PyBoyAdvance


def visual_fingerprint(pixels: np.ndarray) -> dict[str, object]:
    """Return a compact fingerprint suitable for cross-process comparison."""

    if pixels.shape != (160, 240, 3):
        raise ValueError(f"unexpected framebuffer shape: {pixels.shape}")
    colors = np.unique(pixels.reshape(-1, 3), axis=0)
    return {
        "shape": list(pixels.shape),
        "sha256": hashlib.sha256(pixels.tobytes()).hexdigest(),
        "color_count": int(len(colors)),
    }


def qualify_repeated_boot(
    adapter_factory: Callable[[], PyBoyAdvance],
    *,
    frames: int,
    runs: int,
) -> dict[str, object]:
    """Require telemetry and an identical, visible frame across fresh runs."""

    if runs < 2:
        raise ValueError("runs must be at least 2")
    fingerprints: list[dict[str, object]] = []
    for run in range(runs):
        adapter = adapter_factory()
        adapter.require_capabilities("frames", "keys", "pixels", "read_telemetry")
        adapter.frame(frames)
        fingerprint = visual_fingerprint(adapter.pixels())
        if int(fingerprint["color_count"]) < 4:
            raise RuntimeError(
                f"run {run + 1} produced an unusably sparse framebuffer: {fingerprint}"
            )
        fingerprints.append(fingerprint)
    if len({item["sha256"] for item in fingerprints}) != 1:
        raise RuntimeError(f"fresh runs diverged: {fingerprints}")
    return {"runs": runs, "frames": frames, "fingerprint": fingerprints[0]}


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--rom", type=Path, required=True)
    parser.add_argument("--bios", type=Path, required=True)
    parser.add_argument("--frames", type=int, default=900)
    parser.add_argument("--runs", type=int, default=3)
    return parser


def main(argv: list[str] | None = None) -> int:
    args = build_parser().parse_args(argv)

    def factory() -> PyBoyAdvance:
        return PyBoyAdvance(args.rom, args.bios, skip_bios=False, emulation_speed=0)

    try:
        result = qualify_repeated_boot(factory, frames=args.frames, runs=args.runs)
    except (BackendCapabilityError, OSError, RuntimeError, TypeError, ValueError) as exc:
        print(json.dumps({"qualified": False, "error": str(exc)}, sort_keys=True))
        return 1
    print(json.dumps({"qualified": True, **result}, sort_keys=True))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
from __future__ import annotations

import numpy as np
import pytest

from pyboy_adapter import BackendCapabilityError
from qualification import qualify_repeated_boot, visual_fingerprint


class FakeAdapter:
    def __init__(self, pixels: np.ndarray, telemetry: bool = True) -> None:
        self._pixels = pixels
        self._telemetry = telemetry
        self.frame_count = 0

    def require_capabilities(self, *required: str) -> None:
        if "read_telemetry" in required and not self._telemetry:
            raise BackendCapabilityError("missing read-only memory telemetry")

    def frame(self, count: int = 1) -> None:
        self.frame_count += count

    def pixels(self) -> np.ndarray:
        return self._pixels.copy()


def visible_frame(seed: int) -> np.ndarray:
    pixels = np.zeros((160, 240, 3), dtype=np.uint8)
    pixels[:, :, 0] = seed
    pixels[0, 0] = [0, 1, 2]
    pixels[0, 1] = [3, 4, 5]
    pixels[0, 2] = [6, 7, 8]
    return pixels


def test_visual_fingerprint_is_stable_for_same_pixels() -> None:
    assert visual_fingerprint(visible_frame(10)) == visual_fingerprint(visible_frame(10))


def test_qualification_rejects_missing_telemetry() -> None:
    with pytest.raises(BackendCapabilityError, match="telemetry"):
        qualify_repeated_boot(
            lambda: FakeAdapter(visible_frame(10), telemetry=False), frames=3, runs=2
        )


def test_qualification_rejects_divergent_runs() -> None:
    seed = iter([10, 11])
    with pytest.raises(RuntimeError, match="diverged"):
        qualify_repeated_boot(
            lambda: FakeAdapter(visible_frame(next(seed))), frames=3, runs=2
        )


def test_qualification_accepts_identical_visible_runs() -> None:
    result = qualify_repeated_boot(
        lambda: FakeAdapter(visible_frame(10)), frames=3, runs=2
    )
    assert result["runs"] == 2
    assert result["frames"] == 3
from __future__ import annotations

from pathlib import Path

import numpy as np
import pytest

import prototype
from pyboy_adapter import GbaKey, PyBoyAdvance


def test_missing_rom_is_reported(tmp_path: Path) -> None:
    bios = tmp_path / "bios.bin"
    bios.write_bytes(b"\0" * prototype.BIOS_SIZE)
    with pytest.raises(prototype.AssetError, match="ROM does not exist"):
        prototype.validate_assets(tmp_path / "missing.gba", bios)


def test_missing_bios_is_reported(tmp_path: Path) -> None:
    rom = tmp_path / "game.gba"
    rom.write_bytes(b"rom")
    with pytest.raises(prototype.AssetError, match="BIOS does not exist"):
        prototype.validate_assets(rom, tmp_path / "missing.bin")


def test_invalid_bios_size_is_reported(tmp_path: Path) -> None:
    rom = tmp_path / "game.gba"
    bios = tmp_path / "bios.bin"
    rom.write_bytes(b"rom")
    bios.write_bytes(b"\0" * (prototype.BIOS_SIZE - 1))
    with pytest.raises(prototype.AssetError, match="exactly 16384 bytes"):
        prototype.validate_assets(rom, bios)


def test_image_export_failure_is_reported(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> None:
    class BrokenImage:
        def save(self, *args: object, **kwargs: object) -> None:
            raise OSError("disk full")

    monkeypatch.setattr(prototype.Image, "fromarray", lambda *args, **kwargs: BrokenImage())
    pixels = np.zeros((prototype.FRAME_HEIGHT, prototype.FRAME_WIDTH, 3), dtype=np.uint8)
    with pytest.raises(OSError, match="failed to export screenshot"):
        prototype.export_png(pixels, tmp_path / "title.png")


def test_fake_adapter_frame_counter() -> None:
    class FakeAdapter:
        frame_count = 0

        def frame(self, count: int = 1) -> None:
            self.frame_count += count

        def pixels(self) -> np.ndarray:
            return np.zeros((prototype.FRAME_HEIGHT, prototype.FRAME_WIDTH, 3), dtype=np.uint8)

    adapter = FakeAdapter()
    result = prototype.capture(adapter, 900, Path("artifacts/test-title.png"))
    assert adapter.frame_count == 900
    assert result["frames"] == 900
    assert result["framebuffer_dimensions"] == {"width": 240, "height": 160}
    assert result["framebuffer_width"] == 240
    assert result["framebuffer_height"] == 160


def test_input_adapter_tap_releases_key_after_frame_error() -> None:
    class FailingBackend:
        def __init__(self) -> None:
            self.pressed: list[object] = []
            self.released: list[object] = []

        def frame(self, count: int = 1) -> None:
            raise RuntimeError("backend failed")

        def press_key(self, key: object) -> None:
            self.pressed.append(key)

        def release_key(self, key: object) -> None:
            self.released.append(key)

    adapter = object.__new__(PyBoyAdvance)
    adapter._emulator = FailingBackend()
    adapter._frame_count = 0
    with pytest.raises(RuntimeError, match="backend failed"):
        adapter.tap(GbaKey.A)
    assert len(adapter._emulator.pressed) == 1
    assert len(adapter._emulator.released) == 1
"""The first narrow Emerald semantic branch: choosing a starter."""

from __future__ import annotations

from dataclasses import dataclass

from jev_policy import LegalOption, PolicyClient, validate_choice
from pyboy_adapter import GbaKey


STARTER_OPTIONS = (
    LegalOption("TREECKO", "Choose Treecko from the three starter Poké Balls."),
    LegalOption("TORCHIC", "Choose Torchic from the three starter Poké Balls."),
    LegalOption("MUDKIP", "Choose Mudkip from the three starter Poké Balls."),
)


@dataclass(frozen=True)
class StarterObservation:
    """Stable, typed projection of the starter-menu observation."""

    cursor_index: int
    prompt_fingerprint: str

    def state(self) -> dict[str, object]:
        return {
            "phase": "starter_choice",
            "cursor_index": self.cursor_index,
            "prompt_fingerprint": self.prompt_fingerprint,
        }


def choose_starter(
    policy: PolicyClient,
    observation: StarterObservation,
) -> str:
    """Ask Jev to choose only from the three currently legal starters."""

    choice = policy.choose("choose_starter", observation.state(), STARTER_OPTIONS)
    return validate_choice(choice, STARTER_OPTIONS)


def compile_cursor_move(current_index: int, target_id: str) -> list[GbaKey]:
    """Compile a vertical starter choice into relative D-pad input."""

    if not 0 <= current_index < len(STARTER_OPTIONS):
        raise ValueError(f"cursor index out of range: {current_index}")
    targets = {option.option_id: index for index, option in enumerate(STARTER_OPTIONS)}
    if target_id not in targets:
        raise ValueError(f"unknown starter option: {target_id}")
    delta = targets[target_id] - current_index
    key = GbaKey.DOWN if delta > 0 else GbaKey.UP
    return [key] * abs(delta) + [GbaKey.A]
